model Task {
  id: ID
  title: String
  done: Bool
}

component TaskItem(task: Task, onDelete: Fn) {
  row gap=2 align=center {
    checkbox task.done label=task.title
    text task.title muted=task.done
    button "x" small danger -> onDelete(task.id)
  }
}

page Todos "/" {
  state tasks: Task[] = []
  state draft = ""
  computed pending = tasks.filter(t => !t.done).length

  fn add() {
    let t = draft.trim()
    if t == "" { return }
    tasks.push({ id: crypto.randomUUID(), title: t, done: false })
    draft = ""
  }

  column gap=4 pad=4 {
    title "Tareas"
    row gap=2 {
      input draft placeholder="¿Qué hay que hacer?" -> add()
      button "Agregar" primary -> add()
    }
    column gap=2 {
      for t in tasks key t.id {
        TaskItem task=t onDelete=(id => tasks = tasks.filter(x => x.id != id))
      }
    }
    if tasks.length == 0 {
      text "No hay tareas" muted
    } else {
      text `${pending} pendientes` muted
    }
  }
}

page Login "/" {
  state email = ""
  state password = ""
  state sent = false
  computed valid = email.includes("@") && password.length >= 8

