model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  name: String
  price: Number
  qty: Number
}

page Shop "/" {
  meta title="Carrito de compras" description="Carrito de compras simple"

  state products: Product[] = [
    { id: "p1", name: "Camiseta", price: 19.99 },
    { id: "p2", name: "Pantalón", price: 34.5 },
    { id: "p3", name: "Zapatillas", price: 59.95 }
  ]
  state cart: CartItem[] = []

  computed total = cart.reduce((sum, i) => sum + i.price * i.qty, 0)

  fn add(p) {
    let existing = cart.find(i => i.id == p.id)
    if existing {
      existing.qty++
    } else {
      cart.push({ id: p.id, name: p.name, price: p.price, qty: 1 })
    }
  }

  fn inc(item) {
    item.qty++
  }

  fn dec(item) {
    item.qty--
    if item.qty <= 0 {
      cart = cart.filter(i => i.id != item.id)
    }
  }

  column gap=6 pad=6 {
    title "Productos"
    column gap=3 {
      for p in products key p.id {
        card pad=4 {
          row justify=between align=center gap=4 {
            column gap=1 {
              text p.name bold
              text `$${p.price.toFixed(2)}` muted
            }
            button "Agregar" primary -> add(p)
          }
        }
      }
    }

    divider

    title "Carrito"
    if cart.length == 0 {
      text "El carrito está vacío" muted
    } else {
      column gap=3 {
        for item in cart key item.id {
          card pad=4 {
            row justify=between align=center gap=4 {
              column gap=1 {
                text item.name bold
                text `$${(item.price * item.qty).toFixed(2)}` muted
              }
              row gap=2 align=center {
                button "-" small -> dec(item)
                text `${item.qty}`
                button "+" small -> inc(item)
              }
            }
          }
        }
      }
    }

    row justify=between align=center {
      text "Total" bold large
      text `$${total.toFixed(2)}` bold large
    }
  }
}

test "agrega y quita productos" {
