  name: String
  email: String
}

api users: User

page Home "/" {
  state name = ""
  state email = ""
  state error = ""
  data users = api.users.list()

  fn add() {
    if !email.includes("@") {
      error = "Email inválido"
      return
    }
    error = ""
    try {
      await api.users.create({ name: name, email: email })
      name = ""
      email = ""
    } catch (e) {
      error = e.message
    }
  }

  fn removeUser(id) {
    try {
      await api.users.remove(id)
    } catch (e) {
      error = e.message
    }
  }

  column gap=4 pad=4 {
    title "Usuarios"
    row gap=2 {
      input name placeholder="Nombre" -> add()
      input email placeholder="Email" -> add()
      button "Agregar" primary -> add()
    }
    if error != "" {
      text error danger
    }
    if users.loading {
      spinner
    }
    for u in users key u.id {
      row gap=3 align=center {
        text u.name bold
        text u.email muted
        button "Borrar" danger small -> removeUser(u.id)
      }
    }
  }
}

model Item {
  id: ID
  name: String min=1
  bought: Bool = false
}

api items: Item

page Home "/" {
  state draft = ""
  data items = api.items.list()
  computed pending = items.filter(i => !i.bought).length

  fn add() {
    let name = draft.trim()
    if name == "" { return }
    try {
      await api.items.create({ name: name, bought: false })
      draft = ""
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn markBought(item) {
    try {
      await api.items.update(item.id, { bought: true })
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn removeItem(item) {
    try {
      await api.items.remove(item.id)
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  column gap=4 pad=4 {
    title "Lista de compras"
    text `${pending} por comprar` bold
    row gap=2 {
      input draft placeholder="Producto" -> add()
      button "Agregar" primary -> add()
    }
    if items.loading {
      spinner
    }
    for it in items key it.id {
      row gap=2 align=center {
        text (it.bought ? `${it.name} ✓` : it.name) muted=it.bought
        button "Comprado" small disabled=it.bought -> markBought(it)
        button "Borrar" danger small -> removeItem(it)
      }
    }
  }
}

model Author {
  id: ID
  name: String min=1
}

model Post {
  id: ID
  title: String min=1
  author: Author
}

api authors: Author
api posts: Post

page Blog "/" {
  state authorName = ""
  state postTitle = ""
  state selectedAuthor = ""
  state errorMsg = ""

  data authors = api.authors.list()
  data posts = api.posts.list()

  fn createAuthor() {
    if authorName.trim() == "" { return }
    try {
      await api.authors.create({ name: authorName.trim() })
      authorName = ""
      errorMsg = ""
    } catch (e) {
      errorMsg = e.message
    }
  }

  fn publish() {
    if postTitle.trim() == "" || selectedAuthor == "" { return }
    try {
      await api.posts.create({ title: postTitle.trim(), author: selectedAuthor })
      postTitle = ""
      errorMsg = ""
    } catch (e) {
      errorMsg = e.message
    }
  }

  fn deleteAuthor(id) {
    if posts.some(p => p.author?.id == id) {
      errorMsg = "El autor tiene posts"
      return
    }
    try {
      await api.authors.remove(id)
      if selectedAuthor == id { selectedAuthor = "" }
      errorMsg = ""
    } catch (e) {
      errorMsg = "El autor tiene posts"
    }
  }

  column gap=4 pad=4 {
    title "Blog"

    if errorMsg != "" {
      text errorMsg danger
    }

    card gap=2 pad=4 {
      title "Autores" small
      row gap=2 {
        input authorName placeholder="Autor" -> createAuthor()
        button "Crear autor" primary -> createAuthor()
      }
      for a in authors key a.id {
        row gap=2 align=center {
          text a.name
          button "Borrar autor" danger small -> deleteAuthor(a.id)
        }
      }
    }

    card gap=2 pad=4 {
      title "Nuevo post" small
      row gap=2 {
        input postTitle placeholder="Título" -> publish()
        select selectedAuthor options=authors placeholder="Elegí un autor"
        button "Publicar" primary -> publish()
      }
    }

    column gap=2 {
      title "Posts" small
      if posts.length == 0 {
        text "No hay posts" muted
      } else {
        for p in posts key p.id {
          card gap=1 pad=3 {
            text p.title bold
            text `por ${p.author?.name ?? ""}` muted
          }
        }
      }
    }
  }
}

model Product {
  id: ID
  name: String min=3
  code: String unique
  price: Number min=0
}

api products: Product

server fn crearProducto(nombre, codigo, precio) {
  let n = String(nombre ?? "").trim()
  let c = String(codigo ?? "").trim()
  let p = Number(precio)
  if n.length < 3 {
    fail("Nombre muy corto", 400)
  }
  if db.products.count({ where: { code: c } }) > 0 {
    fail("Código repetido", 400)
  }
  if precio == null || precio === "" || Number.isNaN(p) || p < 0 {
    fail("Precio inválido", 400)
  }
  return db.products.create({ name: n, code: c, price: p })
}

page Productos "/" {
  meta title="Registro de productos"
  state nombre = ""
  state codigo = ""
  state precio = ""
  state error = ""
  data productos = api.products.list()

  fn guardar() {
    error = ""
    try {
      await server.crearProducto(nombre, codigo, precio)
      nombre = ""
      codigo = ""
      precio = ""
      productos.reload()
    } catch (e) {
      let m = e.message ?? ""
      if m.includes("Nombre") {
        error = "Nombre muy corto"
      } else {
        if m.includes("Código") {
          error = "Código repetido"
        } else {
          if m.includes("Precio") {
            error = "Precio inválido"
          } else {
            error = m
          }
        }
      }
    }
  }

  column gap=4 pad=4 {
    title "Registro de productos"
    input nombre placeholder="Nombre"
    input codigo placeholder="Código"
    input precio placeholder="Precio" type=number
    button "Guardar" primary -> guardar()
    if error != "" {
      text error danger
    }
    if productos.loading {
      spinner
    }
    for p in productos key p.id {
      card {
        row gap=2 {
          text p.name bold
          text p.code muted
        }
      }
    }
  }
}

model Profile {
  id: ID
  photo: File? max=5000000 accept="image/*"
}

api profiles: Profile

page ProfilePage "/" {
  meta title="Perfil" description="Subí tu foto de perfil"

  state picked: File? = null
  state uploading = false
  data profiles = api.profiles.list({ limit: 1 })
  computed current = profiles.length > 0 ? profiles[0] : null

  fn upload() {
    if !picked { return }
    uploading = true
    try {
      if current {
        await api.profiles.update(current.id, { photo: picked })
      } else {
        await api.profiles.create({ photo: picked })
      }
      picked = null
      notify("Foto subida", "success")
    } catch (e) {
      notify(e.message, "danger")
    }
    uploading = false
  }

  column gap=4 pad=6 align=center {
    title "Perfil"
    card gap=3 pad=4 {
      file picked accept="image/*" label="Foto"
      button "Subir" primary disabled=(!picked || uploading) -> upload()
    }
    if profiles.loading {
      spinner
    } else {
      if current {
        if current.photo {
          image current.photo.url alt="Foto de perfil" width=240
        } else {
          text "Todavía no subiste una foto" muted
        }
      } else {
        text "Todavía no subiste una foto" muted
      }
    }
  }
}

