page Home "/" {
  state items = Array.from({ length: 23 }, (_, i) => `Ítem ${i + 1}`)
  state current = 0
  computed perPage = 10
  computed totalPages = Math.ceil(items.length / perPage)
  computed visible = items.slice(current * perPage, current * perPage + perPage)

  fn prev() {
    if current > 0 { current-- }
  }

  fn next() {
    if current < totalPages - 1 { current++ }
  }

  column gap=4 pad=4 {
    list {
      for it in visible key it {
        item it
      }
    }
    text `Página ${current + 1} de ${totalPages}`
    row gap=2 {
      button "Anterior" disabled=(current == 0) -> prev()
      button "Siguiente" disabled=(current >= totalPages - 1) -> next()
    }
  }
}

