  state n = 0
  state timer: Any = null

  fn iniciar() {
    if timer != null { return }
    timer = setInterval(() => { n++ }, 100)
  }

  fn pausar() {
    if timer != null {
      clearInterval(timer)
      timer = null
    }
  }

  fn reiniciar() {
    pausar()
    n = 0
  }

  mount {
    cleanup { pausar() }
  }

  column gap=4 pad=6 align=center {
    title "Cronómetro"
    text `Tiempo: ${n}` large bold
    row gap=2 {
      button "Iniciar" primary -> iniciar()
      button "Pausar" -> pausar()
      button "Reiniciar" danger -> reiniciar()
    }
  }
}

