page Home "/" {
  meta title="Gestor de tareas" description="Gestor de tareas full-stack"

  state draft = ""
  state filter = "Todas"
  state editing = ""
  state newTitle = ""

  data tasks = api.tasks.list()

  computed shown = filter == "Todas"
    ? tasks
    : filter == "Pendientes"
    ? tasks.filter(t => !t.done)
    : tasks.filter(t => t.done)

  fn add() {
    let title = draft.trim()
    if title == "" { return }
    try {
      await api.tasks.create({ title: title, done: false })
      draft = ""
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn markDone(t) {
    try {
      await api.tasks.update(t.id, { done: true })
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn startRename(t) {
    editing = t.id
    newTitle = t.title
  }

  fn save(t) {
    let title = newTitle.trim()
    if title == "" { return }
    try {
      await api.tasks.update(t.id, { title: title })
      editing = ""
      newTitle = ""
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  column gap=4 pad=4 {
    title "Tareas"
