model Vote {
  id: ID
  choice: String match="^(perros|gatos)$"
}

api votes: Vote

server fn results() {
  let perros = db.votes.count({ where: { choice: "perros" } })
  let gatos = db.votes.count({ where: { choice: "gatos" } })
  let total = perros + gatos
  let pctPerros = total == 0 ? 0 : Math.round(perros * 100 / total)
  let pctGatos = total == 0 ? 0 : Math.round(gatos * 100 / total)
  return { perros, gatos, pctPerros, pctGatos }
}

server fn vote(choice) {
  if choice != "perros" && choice != "gatos" {
    fail("Opción inválida", 400)
  }
  db.votes.create({ choice })
  return true
}

server fn reset() {
  let all = db.votes.list()
  all.forEach(v => db.votes.remove(v.id))
  return true
}

