page Catalog "/" {
  meta title="Catálogo"

  state q = ""
  state page = 0
  state seeding = false

  data items = api.products.list({ search: q || undefined, sort: "num", limit: 5, offset: page * 5 })
  data total = api.products.count({ search: q || undefined })

  computed pages = Math.max(1, Math.ceil(total / 5))

  fn resetPage() {
    page = 0
  }

  fn loadExamples() {
    seeding = true
    try {
      let created = await server.seed()
      if created {
        notify("Ejemplos cargados", "success")
      } else {
        notify("Ya hay productos cargados", "info")
      }
      page = 0
      items.reload()
      total.reload()
    } catch (e) {
      notify(e.message, "danger")
    }
    seeding = false
  }

  fn prev() {
    if page > 0 {
      page--
    }
  }

  fn next() {
    if (page + 1) * 5 < total {
      page++
    }
  }

  column gap=4 pad=6 {
    title "Catálogo"
    row gap=2 align=center {
      button "Cargar ejemplos" primary disabled=seeding -> loadExamples()
      if seeding {
        spinner
      }
    }
    input q placeholder="Buscar" on:input=resetPage()
    text `Total: ${total}` bold
    if items.loading {
      spinner
    } else {
      if items.error {
        text items.error danger
      }
      if items.length == 0 {
        text "No hay productos" muted
      } else {
        list {
          for p in items key p.id {
            item p.name
          }
        }
      }
    }
    row gap=2 align=center {
      button "Anterior" disabled=(page == 0) -> prev()
      text `Página ${page + 1} de ${pages}` muted
      button "Siguiente" disabled=((page + 1) * 5 >= total) -> next()
    }
  }
}

