component Header(count: Number) {
  row justify=between {
    title "Tienda"
    text `Carrito (${count})` muted
  }
}

component Nav(tab: String, onChange: Fn) {
  row gap=2 {
    button "Catálogo" primary=(tab == "catalog") -> onChange("catalog")
    button "Carrito" primary=(tab == "cart") -> onChange("cart")
  }
}

component Catalog(products: Product[], onAdd: Fn) {
  state query = ""
  computed shown = products.filter(p => p.name.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sortByPrice ? a.price - b.price : 0)
  state sortByPrice = false

  column gap=2 {
    input query placeholder="Buscar"
    button "Ordenar por precio" -> sortByPrice = true
    grid cols=3 gap=2 {
      for p in shown {
        ProductCard product=p onAdd=onAdd
      }
    }
    if shown.length == 0 {
      text "Sin resultados" muted
    }
  }
}

component ProductCard(product: Product, onAdd: Fn) {
  card gap=1 {
    text product.name bold
    text `$${product.price.toFixed(2)}`
    button "Agregar" primary -> onAdd(product)
  }
}

component CartView(cart: CartItem[], onChangeQty: Fn, onClear: Fn) {
  if cart.length == 0 {
    text "El carrito está vacío" muted
  } else {
    column gap=2 {
      for item in cart {
        CartItemRow item=item onChangeQty=onChangeQty
      }
      Summary cart=cart onClear=onClear
    }
  }
}

component CartItemRow(item: CartItem, onChangeQty: Fn) {
  row gap=2 {
    text item.product.name
    button "-" -> onChangeQty(item.product.id, -1)
    text item.qty
    button "+" -> onChangeQty(item.product.id, 1)
    text `$${(item.product.price * item.qty).toFixed(2)}`
  }
}

component Summary(cart: CartItem[], onClear: Fn) {
  computed total = cart.reduce((sum, i) => sum + i.product.price * i.qty, 0)

  row justify=between {
    text `Total: $${total.toFixed(2)}` bold
    button "Vaciar carrito" danger -> onClear()
  }
}

component Footer {
  text "Gracias por visitar la tienda" small muted
}

files.shop.art:
model Product {
  id: Number
  name: String
  price: Number
  stock: Number
}

model CartItem {
  product: Product
  qty: Number
}

page Shop "/" {
  state products: Product[] = [{ id: 1, name: "Remera", price: 15, stock: 5 }, { id: 2, name: "Taza", price: 8, stock: 1 }, { id: 3, name: "Gorra", price: 12, stock: 3 }, { id: 4, name: "Mochila", price: 45, stock: 2 }, { id: 5, name: "Lapicera", price: 2, stock: 10 }, { id: 6, name: "Cuaderno", price: 6, stock: 4 }]
  state cart: CartItem[] = []
  state tab = "catalog"
  computed count = cart.reduce((n, i) => n + i.qty, 0)
  fn add(product) {
    let found = cart.find(i => i.product.id == product.id)
    if found {
      found.qty++
    } else {
      cart.push({ product, qty: 1 })
    }
  }
  fn changeQty(id, delta) {
    cart = cart.map(i => i.product.id == id ? { ...i, qty: i.qty + delta } : i).filter(i => i.qty > 0)
  }

  column gap=4 pad=4 {
    Header count=count
    Nav tab=tab onChange=(t => tab = t)
    if tab == "catalog" {
      Catalog products=products onAdd=add
    } else {
      CartView cart=cart onChangeQty=changeQty onClear=(() => cart = [])
    }
    Footer
  }
}

