  }

  column gap=2 {
    title "Empleados"
    EmployeesForm onAdd=add
    EmployeesList items=items
  }
}

component EmployeesList(items: Item[]) {
  fn toggle(id) {
    items = items.map(i => i.id == id ? { ...i, active: !i.active } : i)
  }

  if items.length == 0 {
    text "Sin registros" muted
  } else {
    column gap=1 {
      for item in items {
        row gap=2 align=center {
          EmployeesRow item=item
          button "Alternar" small -> toggle(item.id)
        }
      }
    }
  }
}

component EmployeesRow(item: Item) {
  row gap=2 {
    text item.name bold
